class HashTable:
    """A tiny hash table that resolves collisions with separate chaining."""

    def __init__(self, capacity=8):
        self._buckets = [[] for _ in range(capacity)]
        self._size = 0

    def _bucket(self, key):
        return self._buckets[hash(key) % len(self._buckets)]

    def put(self, key, value):
        bucket = self._bucket(key)
        for i, (existing_key, _) in enumerate(bucket):
            if existing_key == key:
                bucket[i] = (key, value)  # overwrite an existing key
                return
        bucket.append((key, value))
        self._size += 1
        if self._size > 0.75 * len(self._buckets):
            self._resize()

    def get(self, key, default=None):
        for existing_key, value in self._bucket(key):
            if existing_key == key:
                return value
        return default

    def _resize(self):
        pairs = [pair for bucket in self._buckets for pair in bucket]
        self._buckets = [[] for _ in range(len(self._buckets) * 2)]
        for key, value in pairs:
            self._bucket(key).append((key, value))


table = HashTable()
for word in ["cat", "dog", "bird", "fish", "ant"]:
    table.put(word, len(word))

print(table.get("bird"))   # 4
print(table.get("zebra"))  # None

